import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    DoubleSide,
    SRGBColorSpace
  } = ctx.THREE;

  const root = new Group();
  root.name = 'features-card-1';

  const resources = [];
  const disposables = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial({
    side: DoubleSide
  });

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    gradientT
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  resources.push(backdropGeometry, backdropMaterial);

  const cardGeometry = new PlaneGeometry(3.25, 2.03);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: DoubleSide
  });

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'feature-card-surface';
  card.position.set(0, 0.08, 0);
  root.add(card);

  resources.push(cardGeometry, cardMaterial);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    side: DoubleSide
  });

  const topFrameGeometry = new BoxGeometry(3.32, 0.025, 0.035);
  const bottomFrameGeometry = new BoxGeometry(3.32, 0.025, 0.035);
  const sideFrameGeometry = new BoxGeometry(0.025, 2.03, 0.035);

  const topFrame = new Mesh(topFrameGeometry, frameMaterial);
  const bottomFrame = new Mesh(bottomFrameGeometry, frameMaterial);
  const leftFrame = new Mesh(sideFrameGeometry, frameMaterial);
  const rightFrame = new Mesh(sideFrameGeometry, frameMaterial);

  topFrame.position.set(0, 1.105, 0.12);
  bottomFrame.position.set(0, -0.945, 0.12);
  leftFrame.position.set(-1.6475, 0.08, 0.12);
  rightFrame.position.set(1.6475, 0.08, 0.12);

  root.add(topFrame, bottomFrame, leftFrame, rightFrame);
  resources.push(
    topFrameGeometry,
    bottomFrameGeometry,
    sideFrameGeometry,
    frameMaterial
  );

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      if (SRGBColorSpace) texture.colorSpace = SRGBColorSpace;
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }

    root.traverse((child) => {
      if (child.userData?.cleanup && child.userData.cleanup !== root.userData.cleanup) {
        child.userData.cleanup();
      }
    });

    root.clear();
  };

  return root;
}
